<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useWorkforce} from '../context'
import {useWorkforceText} from '../text'
import {employeeDraft,localToday} from '../employeeDraft'
import type {Employee,EmployeeWrite} from '../types'
const {api,home,store,current}=useWorkforce(),route=useRoute(),router=useRouter(),{t,error}=useWorkforceText(),draft=ref<EmployeeWrite|null>(null),busy=ref(false),loading=ref(true),failure=ref(''),originalCompany=ref(''),originalEffectiveDate=ref<string|null>(null)
onMounted(async()=>{try{const e=await api().get<Employee>(`/employees/${route.params.employeeId}`);if(current()&&e.editable&&home.value){draft.value=employeeDraft(home.value,store.value,e);originalCompany.value=e.companyId||'';originalEffectiveDate.value=e.companyEffectiveDate}}catch(e){if(current())failure.value=error(e)}finally{if(current())loading.value=false}})
async function save(){if(!draft.value||busy.value)return;busy.value=true;failure.value='';try{await api().put(`/employees/${route.params.employeeId}`,draft.value);if(current())await router.push(`/stores/${store.value}/workforce/employees`)}catch(e){if(current())failure.value=error(e)}finally{if(current())busy.value=false}}
</script>
<template><section class="wf-panel wf-form-panel"><h2>{{t('assignments')}}<small v-if="draft"> · {{draft.name}}</small></h2><p v-if="failure" role="alert" class="wf-error">{{failure}}</p><p v-if="loading" role="status">{{t('loading')}}</p><form v-else-if="draft" @submit.prevent="save"><fieldset :disabled="busy"><div class="wf-grid"><label>{{t('company')}}<select v-model="draft.companyId" :disabled="!home?.headOffice" required @change="draft.companyEffectiveDate=draft.companyId===originalCompany?originalEffectiveDate:localToday()"><option v-for="c in home?.companies" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>{{t('effectiveDate')}}<input :value="draft.companyEffectiveDate" type="date" disabled></label><label>{{t('mainStore')}}<select v-model="draft.mainStoreId" required><option v-for="s in home?.stores.filter(s=>draft?.storeIds.includes(s.id))" :key="s.id" :value="s.id">{{s.name}}</option></select></label></div><fieldset><legend>{{t('stores')}}</legend><label v-for="s in home?.stores" :key="s.id" class="wf-check"><input v-model="draft.storeIds" type="checkbox" :value="s.id" :disabled="s.id===store||s.id===draft.mainStoreId">{{s.name}}</label></fieldset><p class="wf-hint">{{t('assignmentHint')}}</p><p v-if="draft.accountId" class="wf-hint">{{t('accountHint')}}</p></fieldset><footer class="wf-form-actions"><RouterLink class="wf-button" :to="`/stores/${store}/workforce/employees`">{{t('cancel')}}</RouterLink><button class="primary" :disabled="busy">{{t(busy?'saving':'save')}}</button></footer></form><p v-else-if="!loading" role="alert">{{t('noAccess')}}</p></section></template>
